#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")"
mkdir -p delivery render
OUTPUT_PATH="${OUTPUT_PATH:-delivery/Andar-ou-correr-na-chuva-1080p.mp4}"
mkdir -p -- "$(dirname "$OUTPUT_PATH")"
assembly_tmp=$(mktemp "${OUTPUT_PATH%.mp4}.XXXXXX.mp4")
trap 'rm -f -- "$assembly_tmp"' EXIT
printf "file 'part-00.mp4'\nfile 'part-01.mp4'\nfile 'part-02.mp4'\nfile 'part-03.mp4'\n" > render/concat.txt
ffmpeg -progress render/encoding-progress.txt -hide_banner -loglevel error -y -f concat -safe 0 -i render/concat.txt -i audio/mix.wav -map 0:v:0 -map 1:a:0 -vf 'setsar=1,drawbox=x=165:y=214:w=750:h=65:color=0x11263d:t=fill:enable=gte(t\,26)*lt(t\,33)+gte(t\,206)*lt(t\,216)+gte(t\,216)*lt(t\,225)+gte(t\,241)*lt(t\,251)+gte(t\,365)*lt(t\,374)+gte(t\,448)*lt(t\,453),drawbox=x=1005:y=214:w=750:h=65:color=0x11263d:t=fill:enable=gte(t\,26)*lt(t\,33)+gte(t\,206)*lt(t\,216)+gte(t\,216)*lt(t\,225)+gte(t\,241)*lt(t\,251)+gte(t\,365)*lt(t\,374)+gte(t\,448)*lt(t\,453),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=TEMPO EXPOSTO:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,26)*lt(t\,33),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=ENCONTROS COM GOTAS:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,26)*lt(t\,33),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=TEMPO:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,206)*lt(t\,216),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=DISTÂNCIA:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,206)*lt(t\,216),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=MENOS EXPOSIÇÃO:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,216)*lt(t\,225),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=MESMO TRAJETO:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,216)*lt(t\,225),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=PARCELA SUPERIOR:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,241)*lt(t\,251),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=PARCELA FRONTAL:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,241)*lt(t\,251),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=RECEBER:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,365)*lt(t\,374),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=RETER:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,365)*lt(t\,374),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=POR SEGUNDO:fontcolor=0x74cbd7:fontsize=30:x=480-text_w/2:y=228:enable=gte(t\,448)*lt(t\,453),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=PERCURSO COMPLETO:fontcolor=0xefc75c:fontsize=30:x=1440-text_w/2:y=228:enable=gte(t\,448)*lt(t\,453),drawbox=x=196:y=344:w=680:h=50:color=0x11263d:t=fill:enable=gte(t\,365)*lt(t\,374)+gte(t\,448)*lt(t\,453),drawbox=x=1035:y=344:w=680:h=50:color=0x11263d:t=fill:enable=gte(t\,365)*lt(t\,374)+gte(t\,448)*lt(t\,453),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=CHUVA RECEBIDA:fontcolor=0x9fb7c7:fontsize=27:x=202:y=350:enable=gte(t\,365)*lt(t\,374),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=ÁGUA RETIDA:fontcolor=0x9fb7c7:fontsize=27:x=1042:y=350:enable=gte(t\,365)*lt(t\,374),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=IMPACTO POR SEGUNDO:fontcolor=0x9fb7c7:fontsize=27:x=202:y=350:enable=gte(t\,448)*lt(t\,453),drawtext=fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf:text=DURAÇÃO DO PERCURSO:fontcolor=0x9fb7c7:fontsize=27:x=1042:y=350:enable=gte(t\,448)*lt(t\,453)' -c:v libx264 -threads 4 -preset veryfast -crf 20 -maxrate 1400k -bufsize 2800k -pix_fmt yuv420p -r 24 -c:a aac -b:a 128k -ar 48000 -af 'apad,atrim=duration=480' -t 480 -movflags +faststart -metadata title='Andar ou correr na chuva? — A física do caminho inteiro' "$assembly_tmp"
mv -f -- "$assembly_tmp" "$OUTPUT_PATH"
trap - EXIT
